describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -100, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
      expect(calc.computeShippingCents([makeLine("a", 2)], 1000)).toBe(0);
    });

    it("picks first bracket when weight is within it", () => {
      // 250g * 1 = 250g → bracket upToGrams 500 → 300
      expect(
        calc.computeShippingCents([makeLine("a", 1, 250)], 1000),
      ).toBe(300);
    });

    it("picks bracket at exact boundary", () => {
      // 500g exactly → bracket upToGrams 500 → 300
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 1000),
      ).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      // 501g → bracket upToGrams 2000 → 700
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 1000),
      ).toBe(700);
    });

    it("picks highest bracket for weight at its boundary", () => {
      // 5000g → bracket upToGrams 5000 → 1200
      expect(
        calc.computeShippingCents([makeLine("a", 1, 5000)], 1000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 6000g → overflow → 2000
      expect(
        calc.computeShippingCents([makeLine("a", 1, 6000)], 1000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // 3000g → no overflow defined → last bracket cost = 700
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 1, 3000)], 1000),
      ).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const calcUnsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 250g should match 500 bracket
      expect(
        calcUnsorted.computeShippingCents([makeLine("a", 1, 250)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 300g * 2 + 500g * 1 = 1100g → bracket upToGrams 2000 → 700
      const lines = [makeLine("a", 2, 300), makeLine("b", 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

