      cart.add(product("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies async tax on discounted subtotal", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // discounted subtotal = 1000 - 200 = 800, 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("refreshes prices, checks inventory, computes async tax + shipping", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "FR",
      });
      cart.add(product("a", 1000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.20),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 100 (clamped)
      expect(result.totals.discountCents).toBe(100);
      // discounted subtotal: 2400 - 100 = 2300
      // tax: 20% of 2300 = 460
      expect(result.totals.taxCents).toBe(460);
      // shipping: 500
      expect(result.totals.shippingCents).toBe(500);
      // total: 2300 + 460 + 500 = 3260
      expect(result.totals.totalCents).toBe(3260);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("10% of 1000 cents = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down fractional cents (15% of 999 = 149.85 → 149)", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("100% of subtotal returns the full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% always returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("handles very large subtotals", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(10_000_000)).toBe(2_500_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when fixed amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sum can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // 800 + 500 = 1300, exceeds 1000 — but CompositeDiscountPolicy returns raw sum
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 1000 = 100 → remaining 900; fixed 200 of 900 = 200 → total 300
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(200),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      // Fixed 200 first → remaining 800; 10% of 800 = 80 → total 280
      const compositeA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      // Percentage first → 10% of 1000 = 100 → remaining 900; fixed 200 → total 300
      const compositeB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(200),
        ],
        "chain",
      );
      expect(compositeA.computeDiscountCents(1000)).toBe(280);
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("chain cannot exceed subtotal", () => {
      // 80% of 1000 = 800 → remaining 200; fixed 500 capped at 200 → total 1000
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

