      expect(
        calcUnsorted.computeShippingCents([makeLine("a", 1, 250)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 300g * 2 + 500g * 1 = 1100g → bracket upToGrams 2000 → 700
      const lines = [makeLine("a", 2, 300), makeLine("b", 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
