const product = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  describe("add", () => {
    it("adds a product with quantity", () => {
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);
    });

    it("merges quantity when adding the same product again", () => {
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
      expect(cart.snapshot()).toHaveLength(1);
      expect(cart.snapshot()[0].quantity).toBe(5);
    });

    it("rejects zero quantity", () => {
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.snapshot()).toHaveLength(0);
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
      expect(cart.snapshot()).toEqual([]);
    });
  });

  describe("snapshot isolation", () => {
    it("mutations to snapshot do not affect cart", () => {
      cart.add(product("a", 1000), 1);
      const snap = cart.snapshot();
      snap[0].quantity = 999;
      snap[0].product.unitPriceCents = 0;
      const snap2 = cart.snapshot();
      expect(snap2[0].quantity).toBe(1);
      expect(snap2[0].product.unitPriceCents).toBe(1000);
    });
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("applies discount policy to subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
