    // subtotal=1000, discount=200, discounted=800, tax=80, ship=500
    expect(totals.totalCents).toBe(800 + 80 + 500);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
